package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Pure batch reducer used before a single AppDb transaction commit. Unknown operations fail closed. */
public final class WorldMutationBatchEngine{
 private WorldMutationBatchEngine(){}
 public static JSONObject apply(JSONObject root,JSONArray ops,int defaultDay){JSONObject s=copy(root);if(ops==null)return s;for(int i=0;i<ops.length();i++){JSONObject op=ops.optJSONObject(i);if(op==null)throw new IllegalArgumentException("mutação inválida #"+i);s=applyOne(s,op,defaultDay);}return s;}
 public static JSONObject applyOne(JSONObject s,JSONObject op,int defaultDay){String type=op.optString("operation").trim().toLowerCase();String key=op.optString("entity_key");JSONObject payload=op.optJSONObject("payload");int day=Math.max(1,op.optInt("day",defaultDay));if("npc_memory".equals(type))return LivingWorldPersistenceEngine.rememberNpc(s,key,payload,day);if("faction".equals(type))return LivingWorldPersistenceEngine.applyFaction(s,key,payload,day);if("economy".equals(type))return LivingWorldPersistenceEngine.applyEconomy(s,key,payload,day);if("politics".equals(type))return LivingWorldPersistenceEngine.applyPolitics(s,payload,day);if("mission".equals(type))return LivingWorldPersistenceEngine.addMission(s,payload,day);if("population_upsert".equals(type))return LivingWorldPersistenceEngine.upsertActor(s,payload,day);if("population_spawn_statblock".equals(type))return LivingWorldPersistenceEngine.spawnStatblockActor(s,payload,day);if("population_move".equals(type))return LivingWorldPersistenceEngine.moveActor(s,key,payload==null?"":payload.optString("location"),day);if("population_status".equals(type))return LivingWorldPersistenceEngine.setActorStatus(s,key,payload==null?"active":payload.optString("status","active"),day);if("downtime_upsert".equals(type))return LivingWorldPersistenceEngine.upsertDowntimeProject(s,payload,day);if("downtime_advance".equals(type))return LivingWorldPersistenceEngine.advanceDowntimeProject(s,key,payload==null?0.0:number(payload,"units"),day);if("downtime_status".equals(type))return LivingWorldPersistenceEngine.setDowntimeProjectStatus(s,key,payload==null?"":payload.optString("status"),day);if("job_shift".equals(type))return LivingWorldPersistenceEngine.recordJobShift(s,key,payload==null?0.0:number(payload,"units"),day);if("downtime_resolve".equals(type)){JSONObject x=payload==null?new JSONObject():payload;return LivingWorldPersistenceEngine.resolveDowntimeProject(s,key,x.optString("rule_id"),x.optJSONObject("inputs"),x.optJSONObject("mutation"),day);}if("craft_create".equals(type))return LivingWorldPersistenceEngine.createCrafting(s,payload,day);if("craft_work".equals(type))return LivingWorldPersistenceEngine.workCrafting(s,key,payload,day);if("craft_resolve".equals(type))return LivingWorldPersistenceEngine.resolveCrafting(s,key,payload,day);if("economy_reserve".equals(type))return LivingWorldPersistenceEngine.reserveEconomy(s,payload,day);if("economy_commit".equals(type))return LivingWorldPersistenceEngine.commitEconomy(s,payload,day);if("economy_release".equals(type))return LivingWorldPersistenceEngine.releaseEconomyReserve(s,payload,day);if("cooking_configure".equals(type))return LivingWorldPersistenceEngine.configureCooking(s,payload,day);if("cooking_restock".equals(type))return LivingWorldPersistenceEngine.restockCooking(s,payload,day);if("cooking_prepare".equals(type))return LivingWorldPersistenceEngine.prepareCooking(s,payload,day);if("cooking_feed".equals(type))return LivingWorldPersistenceEngine.feedCooking(s,payload,day);if("cooking_leftovers".equals(type))return LivingWorldPersistenceEngine.cookingLeftovers(s,payload,day);if("mission_resolve".equals(type)){JSONObject x=payload==null?new JSONObject():payload;return LivingWorldPersistenceEngine.resolveMission(s,key,x.optString("status"),x.optString("summary"),day);}if("npc_commitment_resolve".equals(type))return LivingWorldPersistenceEngine.resolveNpcCommitment(s,key,payload==null?"":payload.optString("commitment_key"),day);if("npc_commitment_ack".equals(type))return LivingWorldPersistenceEngine.acknowledgeNpcCommitment(s,key,payload==null?"":payload.optString("commitment_key"),day);if("faction_treaty_ack".equals(type))return LivingWorldPersistenceEngine.acknowledgeFactionTreaty(s,key,payload==null?"":payload.optString("treaty_key"),day);if("politics_decree_ack".equals(type))return LivingWorldPersistenceEngine.acknowledgePoliticalDecree(s,payload==null?"":payload.optString("decree_key"),day);if("patron_configure".equals(type))return LivingWorldPersistenceEngine.configureGroupPatron(s,payload,day);if("patron_assist".equals(type))return LivingWorldPersistenceEngine.patronAssist(s,payload,day);if("patron_assignment_add".equals(type))return LivingWorldPersistenceEngine.addPatronAssignment(s,payload,day);if("patron_assignment_resolve".equals(type))return LivingWorldPersistenceEngine.resolvePatronAssignment(s,key,payload,day);if("sidekick_create".equals(type))return LivingWorldPersistenceEngine.createSidekick(s,payload,day);if("sidekick_level".equals(type))return LivingWorldPersistenceEngine.levelSidekick(s,key,payload,day);if("sidekick_short_rest".equals(type))return LivingWorldPersistenceEngine.sidekickShortRest(s,key,day);if("sidekick_long_rest".equals(type))return LivingWorldPersistenceEngine.sidekickLongRest(s,key,day);if("sidekick_second_wind".equals(type))return LivingWorldPersistenceEngine.sidekickSecondWind(s,key,payload,day);if("sidekick_indomitable".equals(type))return LivingWorldPersistenceEngine.sidekickIndomitable(s,key,payload,day);if("sidekick_expert_help".equals(type))return LivingWorldPersistenceEngine.sidekickExpertHelp(s,key,payload,day);if("sidekick_expert_strike".equals(type))return LivingWorldPersistenceEngine.sidekickExpertStrike(s,key,payload,day);if("sidekick_spell_cast".equals(type))return LivingWorldPersistenceEngine.sidekickSpellCast(s,key,payload,day);if("hazard_avalanche_start".equals(type))return LivingWorldPersistenceEngine.startAvalanche(s,payload,day);if("hazard_avalanche_impact".equals(type))return LivingWorldPersistenceEngine.avalancheImpact(s,key,payload,day);if("hazard_avalanche_stop".equals(type))return LivingWorldPersistenceEngine.stopAvalanche(s,key,day);if("hazard_avalanche_escape".equals(type))return LivingWorldPersistenceEngine.avalancheEscape(s,key,payload,day);if("hazard_spell_create".equals(type))return LivingWorldPersistenceEngine.createSpellEquivalentNaturalHazard(s,payload,day);if("hazard_spell_resolve".equals(type))return LivingWorldPersistenceEngine.resolveSpellEquivalentNaturalHazard(s,key,payload,day);if("supernatural_region_create".equals(type))return LivingWorldPersistenceEngine.createSupernaturalRegion(s,payload,day);if("supernatural_region_trigger".equals(type))return LivingWorldPersistenceEngine.triggerSupernaturalRegion(s,key,payload,day);if("supernatural_region_ack".equals(type))return LivingWorldPersistenceEngine.acknowledgeSupernaturalRegion(s,key,payload,day);if("mystic_storm_start".equals(type))return LivingWorldPersistenceEngine.startMysticStorm(s,payload,day);if("mystic_storm_exposure".equals(type))return LivingWorldPersistenceEngine.mysticStormExposure(s,key,payload,day);if("magical_phenomenon_stop".equals(type))return LivingWorldPersistenceEngine.stopMagicalPhenomenon(s,key,day);if("emotional_echo_create".equals(type))return LivingWorldPersistenceEngine.createEmotionalEcho(s,payload,day);if("emotional_echo_trigger".equals(type))return LivingWorldPersistenceEngine.triggerEmotionalEcho(s,key,payload,day);if("enchanted_fountain_create".equals(type))return LivingWorldPersistenceEngine.createEnchantedFountain(s,payload,day);if("enchanted_fountain_use".equals(type))return LivingWorldPersistenceEngine.useEnchantedFountain(s,key,payload,day);if("mimic_colony_create".equals(type))return LivingWorldPersistenceEngine.createMimicColony(s,payload,day);if("mimic_colony_lair".equals(type))return LivingWorldPersistenceEngine.mimicColonyLairAction(s,key,payload,day);if("mimic_colony_bargain".equals(type))return LivingWorldPersistenceEngine.beginMimicColonyBargain(s,key,payload,day);if("mimic_colony_bargain_resolve".equals(type))return LivingWorldPersistenceEngine.resolveMimicColonyBargain(s,key,payload,day);if("magical_mushroom_create".equals(type))return LivingWorldPersistenceEngine.createMagicalMushroomPatch(s,payload,day);if("magical_mushroom_consume".equals(type))return LivingWorldPersistenceEngine.consumeMagicalMushroom(s,key,payload,day);if("primal_fruit_create".equals(type))return LivingWorldPersistenceEngine.createPrimalFruitPlant(s,payload,day);if("primal_fruit_harvest".equals(type))return LivingWorldPersistenceEngine.harvestPrimalFruit(s,key,payload,day);if("primal_fruit_consume".equals(type))return LivingWorldPersistenceEngine.consumePrimalFruit(s,key,payload,day);if("supernatural_road_create".equals(type))return LivingWorldPersistenceEngine.createSupernaturalRoad(s,payload,day);if("supernatural_road_travel".equals(type))return LivingWorldPersistenceEngine.travelSupernaturalRoad(s,key,payload,day);if("advance_day".equals(type))return LivingWorldPersistenceEngine.advanceDay(s,day);throw new IllegalArgumentException("Operação de Mundo Vivo desconhecida: "+type);}
 private static double number(JSONObject o,String k){if(o==null)return 0.0;try{return Double.parseDouble(String.valueOf(o.opt(k)));}catch(Exception e){return 0.0;}}
 private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}
}
